import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import type { FormEvent, ReactNode } from 'react'
import { io, type Socket } from 'socket.io-client'
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis, LineChart, Line, BarChart, Bar } from 'recharts'
import { Activity, AlertCircle, AlertTriangle, ArrowDownToLine, Bell, Check, ChevronDown, CircleHelp, Clock3, Cpu, Gauge, LayoutDashboard, LogOut, Menu, Plus, Radio, Search, Settings2, ShieldCheck, Thermometer, Wrench, X, Zap, RefreshCw, Filter, FileText, Waves, Power, Database, Wifi, WifiOff } from 'lucide-react'
import type { AlertItem, ApiStatus, MaintenanceItem, Metric, Motor, SensorReading } from './types'
import { initialAlerts, initialHistory, initialMaintenance, initialMotors, makeReading } from './data'
import { useSensorData } from './hooks/useSensorData'
import { API_BASE, apiRequest } from './lib/api'
import { Brand, EmptyState, MetricCard, Panel, SensorCard, StatusPill } from './components'

type Page = 'Overview' | 'Motors' | 'Analytics' | 'Alerts' | 'Maintenance' | 'Reports' | 'Engineering labs'
const pages: { name: Page; icon: typeof LayoutDashboard; group: string }[] = [
  { name: 'Overview', icon: LayoutDashboard, group: 'WORKSPACE' }, { name: 'Motors', icon: Cpu, group: 'WORKSPACE' },
  { name: 'Analytics', icon: Activity, group: 'WORKSPACE' }, { name: 'Alerts', icon: Bell, group: 'WORKSPACE' },
  { name: 'Maintenance', icon: Wrench, group: 'WORKSPACE' }, { name: 'Reports', icon: FileText, group: 'MANAGEMENT' },
  { name: 'Engineering labs', icon: Settings2, group: 'MANAGEMENT' },
]
const fmtTime = (s: string) => new Date(s).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
const fmtDate = (s: string) => new Date(s).toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
const csvEscape = (v: unknown) => `"${String(v ?? '').replaceAll('"', '""')}"`
function downloadCsv(rows: Record<string, unknown>[], filename: string) {
  if (!rows.length) return
  const keys = Object.keys(rows[0])
  const csv = [keys.map(csvEscape).join(','), ...rows.map(row => keys.map(k => csvEscape(row[k])).join(','))].join('\n')
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8;' }))
  const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); URL.revokeObjectURL(url)
}
function App() {
  const [page, setPage] = useState<Page>('Overview')
  const [authenticated, setAuthenticated] = useState(() => localStorage.getItem('motorvibe_demo_session') === 'true')
  const [authMode, setAuthMode] = useState<'login'|'register'>('login')
  const [authName, setAuthName] = useState('')
  const [authEmail, setAuthEmail] = useState('')
  const [authPassword, setAuthPassword] = useState('')
  const [authError, setAuthError] = useState('')
  const [authLoading, setAuthLoading] = useState(false)
  const [motors, setMotors] = useState<Motor[]>(initialMotors)
  const [alerts, setAlerts] = useState<AlertItem[]>(initialAlerts)
  const [maintenance, setMaintenance] = useState<MaintenanceItem[]>(initialMaintenance)
  const [history, setHistory] = useState<SensorReading[]>(initialHistory)
  const [autoRun, setAutoRun] = useState(true)
  const [emergencyStop, setEmergencyStop] = useState(false)
  const [unit, setUnit] = useState<'C'|'F'>('C')
  const [query, setQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState('All statuses')
  const [sortBy, setSortBy] = useState<'name'|'health'|'vibration'|'temperature'>('name')
  const [editingMotorId, setEditingMotorId] = useState<string | null>(null)
  const [selectedMotor, setSelectedMotor] = useState('All motors')
  const [showAddMotor, setShowAddMotor] = useState(false)
  const [showAddWork, setShowAddWork] = useState(false)
  const [showProfile, setShowProfile] = useState(false)
  const [toast, setToast] = useState('')
  const [mobileNav, setMobileNav] = useState(false)
  const [protocol, setProtocol] = useState<'Socket.IO'|'Polling'|'SSE'>('Socket.IO')
  const [apiStatus, setApiStatus] = useState<ApiStatus>({ mode: 'demo', message: 'Running with simulated telemetry' })
  const [lastUpdate, setLastUpdate] = useState(new Date())
  const [tempInput, setTempInput] = useState({ name: '', location: '', model: '' })
  const [workInput, setWorkInput] = useState({ motorId: 'MTR-003', task: '', dueDate: '2026-10-20', priority: 'Medium' as MaintenanceItem['priority'] })
  const [labTab, setLabTab] = useState<'TempDash'|'PressureDash'|'VoltDash'|'PowerDash'|'HumidDash'|'SpeedDash'|'PulseDash'>('TempDash')
  const [labUnit, setLabUnit] = useState<'primary'|'alternate'>('primary')
  const [labValue, setLabValue] = useState(25)
  const [labVoltage, setLabVoltage] = useState(4.5)
  const [labCurrent, setLabCurrent] = useState(1.2)
  const [apiLabLoading, setApiLabLoading] = useState(false)
  const [apiLabError, setApiLabError] = useState('')
  const [apiLabResult, setApiLabResult] = useState<{ temperature: number; humidity: number; pressure: number } | null>(null)
  const [apiKeyInput, setApiKeyInput] = useState('')
  const [labHistory, setLabHistory] = useState<{ time: string; value: number }[]>([])
  const [labRunning, setLabRunning] = useState(false)
  const labCount = useRef(0)
  const { history: liveHistory, addReading, updatesRef, abnormalRef } = useSensorData(motors, autoRun && !emergencyStop)
  const activeReading = history[history.length - 1]
  const mergedHistory = useMemo(() => [...history, ...liveHistory].slice(-60), [history, liveHistory])
  const activeMotor = motors.find(m => m.id === (activeReading?.motorId || 'MTR-001')) ?? motors[0]
  const healthy = motors.filter(m => m.status === 'Healthy').length
  const warnings = motors.filter(m => m.status === 'Warning').length
  const critical = motors.filter(m => m.status === 'Critical').length
  const avgHealth = Math.round(motors.reduce((sum, m) => sum + m.health, 0) / Math.max(1, motors.length))
  const unacknowledged = alerts.filter(a => !a.acknowledged).length
  const filteredMotors = useMemo(() => motors.filter(m => (statusFilter === 'All statuses' || m.status === statusFilter) && `${m.id} ${m.name} ${m.location} ${m.model}`.toLowerCase().includes(query.toLowerCase())).sort((a,b) => sortBy === 'name' ? a.name.localeCompare(b.name) : sortBy === 'health' ? a.health-b.health : sortBy === 'vibration' ? b.vibration-a.vibration : b.temperature-a.temperature), [motors, statusFilter, query, sortBy])
  const trendData = useMemo(() => mergedHistory.slice(-24).map(r => ({ time: fmtTime(r.timestamp), vibration: r.vibration, temperature: r.temperature, health: r.health })), [mergedHistory])
  const toastMsg = useCallback((message: string) => { setToast(message); window.setTimeout(() => setToast(''), 3000) }, [])
  useEffect(() => {
    const timer = window.setInterval(() => setLastUpdate(new Date()), 1000)
    return () => window.clearInterval(timer)
  }, [])
  useEffect(() => {
    if (!liveHistory.length) return
    const reading = liveHistory[liveHistory.length - 1]
    setHistory(prev => [...prev, reading].slice(-60))
    setLastUpdate(new Date())
    if (reading.status !== 'Healthy') {
      const id = `ALT-${Date.now().toString().slice(-5)}`
      setAlerts(prev => [{ id, motorId: reading.motorId, motorName: reading.motorName, severity: reading.status, message: `Vibration ${reading.vibration} mm/s · temperature ${reading.temperature}°C`, timestamp: reading.timestamp, acknowledged: false }, ...prev].slice(0, 40))
    }
  }, [liveHistory])
  useEffect(() => {
    let socket: Socket | null = null
    let source: EventSource | null = null
    let pollTimer: number | undefined
    let cancelled = false
    const connect = async () => {
      try {
        await apiRequest<{ ok: boolean }>('/api/health')
        if (cancelled) return
        setApiStatus({ mode: 'connected', message: 'API connected · PostgreSQL may be enabled' })
        if (protocol === 'Socket.IO') {
          socket = io(API_BASE, { transports: ['websocket', 'polling'], reconnectionAttempts: 2, timeout: 1800 })
          socket.on('connect', () => setApiStatus({ mode: 'connected', message: 'Connected · Socket.IO live transport' }))
          socket.on('telemetry:reading', (reading: SensorReading) => { setHistory(prev => [...prev, reading].slice(-60)); setLastUpdate(new Date()) })
          socket.on('connect_error', () => setApiStatus({ mode: 'demo', message: 'API reachable · local simulated stream active' }))
        } else if (protocol === 'Polling') {
          pollTimer = window.setInterval(async () => {
            try {
              const rows = await apiRequest<Array<{ id: number; sensor_id: string; metric_value: number; motor_name?: string; timestamp: string; vibration?: number; temperature?: number; rpm?: number; current?: number }>>('/api/sensors/MTR-001/history?hours=1')
              const readings = rows.slice(0, 5).map(row => ({ id: String(row.id), motorId: row.sensor_id, motorName: row.motor_name || row.sensor_id, timestamp: row.timestamp, vibration: Number(row.vibration ?? row.metric_value), temperature: Number(row.temperature ?? 25), rpm: Number(row.rpm ?? 0), current: Number(row.current ?? 0), health: 100, status: 'Healthy' as const, simulated: false }))
              if (readings.length) setHistory(prev => [...prev, ...readings].slice(-60))
            } catch { /* The local demo stream remains available when persistence is not configured. */ }
          }, 5000)
        } else if (protocol === 'SSE') {
          source = new EventSource(`${API_BASE}/api/events`)
          source.onmessage = event => { try { const reading = JSON.parse(event.data) as SensorReading; setHistory(prev => [...prev, reading].slice(-60)) } catch { /* ignore malformed event */ } }
          source.onerror = () => setApiStatus({ mode: 'demo', message: 'SSE unavailable · local simulated stream active' })
        }
      } catch {
        if (!cancelled) setApiStatus({ mode: 'demo', message: 'Demo mode · API not connected; simulated values are clearly labelled' })
      }
    }
    void connect()
    return () => { cancelled = true; socket?.disconnect(); source?.close(); if (pollTimer !== undefined) window.clearInterval(pollTimer) }
  }, [protocol])
  const addMotor = (e: FormEvent) => {
    e.preventDefault()
    const motor: Motor = { id: `MTR-${String(Date.now()).slice(-3)}`, name: tempInput.name.trim(), location: tempInput.location.trim(), model: tempInput.model.trim() || 'Custom motor', vibration: 2.4, temperature: 54, rpm: 1450, current: 7.5, health: 96, status: 'Healthy', lastService: new Date().toISOString().slice(0, 10) }
    if (!motor.name || !motor.location) return
    if (editingMotorId) {
      const patch = { name: motor.name, location: motor.location, model: motor.model }
      setMotors(prev => prev.map(existing => existing.id === editingMotorId ? { ...existing, ...patch } : existing))
      void apiRequest(`/api/sensors/${editingMotorId}`, { method: 'PATCH', body: JSON.stringify(patch) }).catch(() => undefined)
      setEditingMotorId(null); setTempInput({ name: '', location: '', model: '' }); setShowAddMotor(false); toastMsg('Motor details updated')
      return
    }
    setMotors(prev => [...prev, motor]); setTempInput({ name: '', location: '', model: '' }); setShowAddMotor(false); toastMsg('Motor added to the local dashboard')
    void apiRequest('/api/sensors', { method: 'POST', body: JSON.stringify(motor) }).catch(() => undefined)
  }
  const deleteMotor = (motor: Motor) => {
    setMotors(prev => prev.filter(m => m.id !== motor.id)); toastMsg(`${motor.name} removed from this demo view`)
    void apiRequest(`/api/sensors/${motor.id}`, { method: 'DELETE' }).catch(() => undefined)
  }
  const acknowledge = (id: string) => {
    setAlerts(prev => prev.map(a => a.id === id ? { ...a, acknowledged: true } : a)); toastMsg('Alert acknowledged')
    void apiRequest(`/api/alerts/${id}/acknowledge`, { method: 'PATCH' }).catch(() => undefined)
  }
  const addWork = (e: FormEvent) => {
    e.preventDefault()
    const motor = motors.find(m => m.id === workInput.motorId)
    if (!motor || !workInput.task.trim()) return
    const item: MaintenanceItem = { id: `WO-${Date.now().toString().slice(-4)}`, motorId: motor.id, motorName: motor.name, task: workInput.task.trim(), dueDate: workInput.dueDate, priority: workInput.priority, status: 'Scheduled' }
    setMaintenance(prev => [item, ...prev]); setShowAddWork(false); setWorkInput({ motorId: motors[0]?.id ?? '', task: '', dueDate: '2026-10-20', priority: 'Medium' }); toastMsg('Maintenance work order created')
    void apiRequest('/api/maintenance', { method: 'POST', body: JSON.stringify(item) }).catch(() => undefined)
  }
  const updateWorkStatus = (item: MaintenanceItem) => {
    const next = item.status === 'Scheduled' ? 'In progress' : item.status === 'In progress' ? 'Completed' : 'Scheduled'
    setMaintenance(prev => prev.map(w => w.id === item.id ? { ...w, status: next } : w)); toastMsg(`Work order marked ${next.toLowerCase()}`)
    void apiRequest(`/api/maintenance/${item.id}`, { method: 'PATCH', body: JSON.stringify({ status: next }) }).catch(() => undefined)
  }
  const exportReadings = () => { downloadCsv(mergedHistory.map(r => ({ timestamp: r.timestamp, motor: r.motorName, motorId: r.motorId, vibration_mm_s: r.vibration, temperature_c: r.temperature, rpm: r.rpm, current_a: r.current, health: r.health, status: r.status, source: r.simulated ? 'SIMULATED' : 'API' })), 'motorvibe-telemetry.csv'); toastMsg('Telemetry CSV exported') }
  const exportMotors = () => { downloadCsv(motors as unknown as Record<string, unknown>[], 'motorvibe-motors.csv'); toastMsg('Motor inventory exported') }
  const generateLabReading = () => {
    const voltage = +(Math.random() * 12).toFixed(2)
    const current = +(Math.random() * 1.5).toFixed(2)
    if (labTab === 'PowerDash') { setLabVoltage(voltage); setLabCurrent(current) }
    const value = labTab === 'TempDash' ? Math.floor(Math.random() * 50) : labTab === 'PressureDash' ? Math.floor(50000 + Math.random() * 220000) : labTab === 'VoltDash' ? voltage : labTab === 'PowerDash' ? +(voltage * current).toFixed(2) : labTab === 'HumidDash' ? Math.floor(Math.random() * 101) : labTab === 'SpeedDash' ? Math.floor(Math.random() * 160) : Math.floor(45 + Math.random() * 75)
    setLabValue(value); setLabHistory(prev => [...prev, { time: fmtTime(new Date().toISOString()), value }].slice(-60)); labCount.current += 1
    if (labTab === 'TempDash' && value > 40 && labRunning) { setLabRunning(false); toastMsg('Stopped due to abnormal reading.') }
  }
  const fetchWeatherLab = async () => {
    setApiLabLoading(true); setApiLabError('')
    try {
      const response = await fetch('https://api.open-meteo.com/v1/forecast?latitude=17.3850&longitude=78.4867&current=temperature_2m,relative_humidity_2m,pressure_msl')
      if (!response.ok) throw new Error(response.status === 401 ? 'API key missing or invalid.' : 'Network unavailable. Please try again.')
      const data = await response.json()
      setApiLabResult({ temperature: data.current.temperature_2m, humidity: data.current.relative_humidity_2m, pressure: data.current.pressure_msl })
    } catch (err) {
      setApiLabError(err instanceof Error ? err.message : 'Network unavailable. Please try again.')
    } finally { setApiLabLoading(false) }
  }
  const validateApiKeyDemo = () => {
    if (!apiKeyInput.trim()) setApiLabError('API key missing or invalid.')
    else setApiLabError('Key input captured for the exercise. Configure a provider endpoint and validate the key server-side before production use.')
  }
  useEffect(() => {
    if (!labRunning) return
    const timer = window.setInterval(() => generateLabReading(), 2000)
    return () => window.clearInterval(timer)
  }, [labRunning, labTab])
  const authenticate = async (e: FormEvent) => {
    e.preventDefault()
    setAuthError('')
    setAuthLoading(true)
    try {
      if (authMode === 'register') {
        await apiRequest('/api/auth/register', { method: 'POST', body: JSON.stringify({ name: authName, email: authEmail, password: authPassword }) })
      }
      const result = await apiRequest<{ token: string }>('/api/auth/login', { method: 'POST', body: JSON.stringify({ email: authEmail, password: authPassword }) })
      localStorage.setItem('motorvibe_token', result.token)
      localStorage.setItem('motorvibe_demo_session', 'true')
      setAuthenticated(true)
    } catch (err) {
      setAuthError(err instanceof Error ? err.message : 'Could not connect to the authentication API.')
    } finally {
      setAuthLoading(false)
    }
  }
  const continueDemo = () => {
    localStorage.removeItem('motorvibe_token')
    localStorage.setItem('motorvibe_demo_session', 'true')
    setAuthenticated(true)
    setAuthError('')
  }
  const stopSystem = () => { setEmergencyStop(true); setAutoRun(false); setLabRunning(false); toastMsg('Emergency stop activated · live simulation paused') }
  const restartSystem = () => { setEmergencyStop(false); setAutoRun(true); toastMsg('Monitoring restarted') }

  if (!authenticated) return <AuthScreen
    mode={authMode} setMode={setAuthMode} name={authName} setName={setAuthName}
    email={authEmail} setEmail={setAuthEmail} password={authPassword} setPassword={setAuthPassword}
    error={authError} loading={authLoading} onSubmit={authenticate} onDemo={continueDemo}
  />

  const sidebar = <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}>
    <div className="px-5 pb-8 pt-6"><Brand/></div>
    <div className="mx-4 mb-3 rounded-xl border border-emerald-400/10 bg-emerald-400/[.05] px-3 py-3"><div className="flex items-center gap-2 text-xs font-semibold text-emerald-300"><span className="live-dot"/>{emergencyStop ? 'SYSTEM PAUSED' : 'SYSTEM OPERATIONAL'}</div><p className="mt-1.5 text-[10px] text-slate-500">Plant 01 · Hyderabad</p></div>
    {['WORKSPACE', 'MANAGEMENT'].map(group => <div key={group} className="mb-5"><p className="nav-group">{group}</p>{pages.filter(p => p.group === group).map(item => { const Icon = item.icon; return <button key={item.name} className={`nav-item ${page === item.name ? 'nav-active' : ''}`} onClick={() => { setPage(item.name); setMobileNav(false) }}><Icon size={17}/><span>{item.name}</span>{item.name === 'Alerts' && unacknowledged > 0 && <span className="nav-count">{unacknowledged}</span>}</button> })}</div>)}
    <div className="mt-auto px-4 pb-5"><div className="rounded-xl border border-white/[.06] bg-white/[.025] p-3"><div className="flex items-center gap-2 text-xs text-slate-300"><Database size={15} className="text-emerald-300"/>Telemetry pipeline</div><div className="mt-3 flex items-center justify-between text-[10px] text-slate-500"><span>{apiStatus.mode === 'connected' ? 'API connected' : 'Simulation mode'}</span><span className="flex items-center gap-1"><span className={`h-1.5 w-1.5 rounded-full ${apiStatus.mode === 'connected' ? 'bg-emerald-400' : 'bg-amber-400'}`}/>{apiStatus.mode === 'connected' ? 'Live' : 'Demo'}</span></div></div><button className="nav-item mt-4" onClick={() => setShowProfile(v => !v)}><div className="avatar">SH</div><div className="min-w-0 flex-1 text-left"><div className="truncate text-xs font-semibold text-slate-200">Site Operator</div><div className="text-[10px] text-slate-500">Administrator</div></div><ChevronDown size={14}/></button>{showProfile && <div className="px-3 pb-2 text-xs text-slate-400"><button onClick={() => { localStorage.removeItem('motorvibe_token'); localStorage.removeItem('motorvibe_demo_session'); setAuthenticated(false); toastMsg('Session ended') }} className="flex items-center gap-2 py-2"><LogOut size={14}/> Sign out demo session</button></div>}</div>
  </aside>

  return <div className="app-shell">
    {sidebar}
    {mobileNav && <button className="mobile-scrim" aria-label="Close navigation" onClick={() => setMobileNav(false)}/>}
    <main className="main-content">
      <header className="topbar"><div className="flex items-center gap-3"><button className="icon-button lg:hidden" onClick={() => setMobileNav(v => !v)} aria-label="Open navigation"><Menu size={18}/></button><div><div className="flex items-center gap-2"><span className="eyebrow">INDUSTRIAL MONITORING / PLANT 01</span><span className="hidden rounded-md border border-emerald-400/15 bg-emerald-400/[.06] px-2 py-1 text-[9px] font-bold tracking-wider text-emerald-300 sm:inline-flex">BETA</span></div><h1 className="page-heading">{page === 'Overview' ? 'Operational overview' : page}</h1></div></div><div className="flex items-center gap-3"><div className="hidden items-center gap-2 rounded-lg border border-white/[.07] bg-white/[.025] px-3 py-2 text-[11px] text-slate-400 md:flex"><Clock3 size={13}/>{lastUpdate.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}<span className="mx-1 h-3 w-px bg-white/10"/><span className="live-dot"/>Monitoring active</div><button className="icon-button relative" onClick={() => setPage('Alerts')} aria-label="Open alerts"><Bell size={17}/>{unacknowledged > 0 && <span className="notification-dot"/>}</button><div className="avatar hidden sm:flex">SH</div></div></header>
      <div className="content-wrap">
        <div className="mb-5 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><span className={`h-2 w-2 rounded-full ${emergencyStop ? 'bg-rose-400' : 'bg-emerald-400'}`}/><span className="text-xs text-slate-400">{emergencyStop ? 'Emergency stop engaged' : 'All systems monitored'}</span><span className="text-slate-700">/</span><span className="text-xs text-slate-500">{apiStatus.message}</span></div><div className="flex flex-wrap items-center gap-2"><select className="select-control" value={protocol} onChange={e => setProtocol(e.target.value as typeof protocol)} aria-label="Real-time protocol"><option>Socket.IO</option><option>Polling</option><option>SSE</option></select><button className="btn-secondary" onClick={() => { setAutoRun(v => !v); toastMsg(autoRun ? 'Auto-refresh paused' : 'Auto-refresh resumed') }}><RefreshCw size={14}/>{autoRun ? 'Pause stream' : 'Resume stream'}</button>{emergencyStop ? <button className="btn-primary" onClick={restartSystem}><Power size={14}/>Restart</button> : <button className="btn-danger" onClick={stopSystem}><Power size={14}/>Emergency stop</button>}</div></div>

        {page === 'Overview' && <>
          <section className="hero-panel mb-5"><div className="hero-orb hero-orb-one"/><div className="hero-orb hero-orb-two"/><div className="relative z-10 flex flex-col justify-between gap-6 lg:flex-row lg:items-center"><div className="max-w-xl"><div className="mb-3 flex items-center gap-2"><span className="hero-tag"><Activity size={12}/> CONDITION MONITORING</span><span className="text-[10px] text-slate-500">UPDATED JUST NOW</span></div><h2 className="max-w-lg text-2xl font-semibold leading-tight tracking-tight text-white sm:text-[30px]">Know your machines.<br/><span className="text-emerald-300">Before they fail.</span></h2><p className="mt-3 max-w-lg text-sm leading-6 text-slate-400">A live view of motor health, vibration trends and maintenance risk across your plant floor.</p><div className="mt-5 flex flex-wrap gap-2"><button className="btn-primary" onClick={() => setPage('Analytics')}>View analytics <ChevronDown size={14} className="-rotate-90"/></button><button className="btn-secondary" onClick={() => setPage('Motors')}><Cpu size={14}/>Motor inventory</button></div></div><div className="hero-status"><div className="flex items-center justify-between"><span className="text-xs text-slate-400">Fleet health index</span><ShieldCheck size={17} className="text-emerald-300"/></div><div className="mt-4 flex items-end gap-2"><span className="text-5xl font-semibold tracking-tight text-white">{avgHealth}</span><span className="mb-2 text-sm text-slate-500">/ 100</span></div><div className="mt-4 h-1.5 overflow-hidden rounded-full bg-white/[.08]"><div className="h-full rounded-full bg-gradient-to-r from-emerald-500 to-teal-300" style={{ width: `${avgHealth}%` }}/></div><div className="mt-3 flex items-center justify-between text-[10px]"><span className="text-emerald-300">Fleet condition</span><span className="text-slate-500">{motors.length} assets tracked</span></div></div></div></section>
          <section className="mb-5 grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Total motors" value={motors.length.toString().padStart(2,'0')} note="Assets registered" icon={<Cpu size={18}/>} tone="blue"/><MetricCard label="Healthy motors" value={healthy.toString().padStart(2,'0')} note="Operating within limits" icon={<ShieldCheck size={18}/>} tone="green"/><MetricCard label="Needs attention" value={(warnings + critical).toString().padStart(2,'0')} note={`${critical} critical · ${warnings} warning`} icon={<AlertTriangle size={18}/>} tone={critical ? 'red' : 'amber'} trend={critical ? 'up' : undefined}/><MetricCard label="Open alerts" value={unacknowledged.toString().padStart(2,'0')} note="Awaiting acknowledgement" icon={<Bell size={18}/>} tone="amber"/></section>
          <section className="grid grid-cols-1 gap-5 2xl:grid-cols-[minmax(0,1.65fr)_minmax(310px,1fr)]"><div className="space-y-5"><Panel title="Live vibration signature" subtitle="Rolling telemetry window · last 24 samples" action={<span className="chart-legend"><i/> Vibration <span className="ml-3 text-slate-500">mm/s</span></span>}><div className="h-[255px] w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trendData} margin={{ top: 8, right: 4, left: -20, bottom: 0 }}><defs><linearGradient id="vibFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#35d6a1" stopOpacity={.22}/><stop offset="95%" stopColor="#35d6a1" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="rgba(148,163,184,.09)" vertical={false}/><XAxis dataKey="time" tick={{ fill: '#64748b', fontSize: 10 }} tickLine={false} axisLine={false} minTickGap={35}/><YAxis tick={{ fill: '#64748b', fontSize: 10 }} tickLine={false} axisLine={false} domain={[0, 'auto']}/><Tooltip contentStyle={{ background: '#0d202b', border: '1px solid #243945', borderRadius: 10, color: '#e2e8f0', fontSize: 12 }} labelStyle={{ color: '#94a3b8' }}/><Area type="monotone" dataKey="vibration" stroke="#35d6a1" strokeWidth={2} fill="url(#vibFill)" activeDot={{ r: 4, fill: '#35d6a1', stroke: '#071b25', strokeWidth: 2 }}/></AreaChart></ResponsiveContainer></div><div className="mt-4 flex flex-wrap items-center justify-between gap-2 border-t border-white/[.06] pt-4"><div className="flex items-center gap-2 text-xs text-slate-400"><span className="live-dot"/>Auto-updating {autoRun && !emergencyStop ? 'every 2.5 seconds' : 'paused'}</div><button className="text-xs font-semibold text-emerald-300 hover:text-emerald-200" onClick={() => setPage('Analytics')}>Explore telemetry <ChevronDown size={13} className="inline -rotate-90"/></button></div></Panel>
            <Panel title="Motor fleet" subtitle="Current operating condition across registered assets" action={<button className="text-xs font-semibold text-emerald-300" onClick={() => setPage('Motors')}>View all <ChevronDown size={12} className="inline -rotate-90"/></button>}><div className="table-wrap"><table><thead><tr><th>Motor / location</th><th>Vibration</th><th>Temperature</th><th>Health</th><th>Status</th></tr></thead><tbody>{motors.slice(0, 4).map(m => <tr key={m.id}><td><div className="flex items-center gap-3"><div className="table-motor-icon"><Cpu size={15}/></div><div><p className="font-semibold text-slate-200">{m.name}</p><p className="mt-1 text-[10px] text-slate-500">{m.id} · {m.location}</p></div></div></td><td><span className={m.vibration >= 8 ? 'text-rose-300' : 'text-slate-300'}>{m.vibration.toFixed(1)} <small className="text-slate-500">mm/s</small></span></td><td><span className={m.temperature >= 85 ? 'text-rose-300' : 'text-slate-300'}>{unit === 'C' ? `${m.temperature}°C` : `${(m.temperature * 1.8 + 32).toFixed(1)}°F`}</span></td><td><div className="flex items-center gap-2"><div className="health-bar"><i style={{ width: `${m.health}%` }}/></div><span className="text-xs text-slate-400">{m.health}%</span></div></td><td><StatusPill status={m.status}/></td></tr>)}</tbody></table></div></Panel></div>
            <div className="space-y-5"><Panel title="Sensor snapshot" subtitle="Latest aggregate readings" action={<span className="text-[10px] text-slate-500">SIMULATED DATA</span>}><div className="grid grid-cols-1 gap-3 sm:grid-cols-2 2xl:grid-cols-1"><SensorCard meta={{ name: 'Vibration RMS', unit: 'mm/s', description: 'Overall vibration' }} value={(activeMotor?.vibration ?? 0).toFixed(1)} unit="mm/s" detail="ISO 10816 reference" abnormal={(activeMotor?.vibration ?? 0) >= 5}/><SensorCard meta={{ name: 'Temperature', unit: '°C', description: 'Motor casing' }} value={unit === 'C' ? activeMotor?.temperature : ((activeMotor?.temperature ?? 0) * 1.8 + 32).toFixed(1)} unit={unit === 'C' ? '°C' : '°F'} detail="Thermal monitoring" abnormal={(activeMotor?.temperature ?? 0) >= 85}/></div><div className="mt-4 flex items-center justify-between border-t border-white/[.06] pt-4"><span className="text-xs text-slate-500">Temperature display</span><div className="segmented"><button className={unit === 'C' ? 'selected' : ''} onClick={() => setUnit('C')}>°C</button><button className={unit === 'F' ? 'selected' : ''} onClick={() => setUnit('F')}>°F</button></div></div></Panel>
              <Panel title="Priority alerts" subtitle="Events requiring operator attention" action={<button className="icon-button compact" onClick={() => setPage('Alerts')} aria-label="View all alerts"><ChevronDown size={14} className="-rotate-90"/></button>}>{alerts.filter(a => !a.acknowledged).slice(0, 3).map(a => <div key={a.id} className="alert-row"><div className={`alert-symbol ${a.severity === 'Critical' ? 'alert-symbol-red' : 'alert-symbol-amber'}`}><AlertTriangle size={15}/></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><p className="truncate text-xs font-semibold text-slate-200">{a.motorName}</p><StatusPill status={a.severity}/></div><p className="mt-1 text-[11px] leading-5 text-slate-500">{a.message}</p><p className="mt-1 text-[10px] text-slate-600">{fmtDate(a.timestamp)}</p></div></div>)}{unacknowledged === 0 && <EmptyState title="All caught up" text="No unacknowledged alerts."/>}<button className="btn-secondary mt-4 w-full justify-center" onClick={() => setPage('Alerts')}>Open alert center <ChevronDown size={13} className="-rotate-90"/></button></Panel>
              <Panel title="Maintenance queue" subtitle="Upcoming service activities" action={<Wrench size={16} className="text-slate-500"/>}>{maintenance.filter(w => w.status !== 'Completed').slice(0, 3).map(w => <div key={w.id} className="maintenance-mini"><div className="maintenance-date"><span>{new Date(`${w.dueDate}T12:00:00`).toLocaleDateString([], { month: 'short' })}</span><strong>{new Date(`${w.dueDate}T12:00:00`).getDate()}</strong></div><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold text-slate-200">{w.task}</p><p className="mt-1 truncate text-[10px] text-slate-500">{w.motorName}</p></div><span className={`priority-dot priority-${w.priority.toLowerCase()}`}/></div>)}<button className="mt-3 text-xs font-semibold text-emerald-300" onClick={() => setPage('Maintenance')}>Manage work orders <ChevronDown size={13} className="inline -rotate-90"/></button></Panel></div></section>
        </>}

        {page === 'Motors' && <><div className="mb-5 grid grid-cols-1 gap-3 sm:grid-cols-3"><MetricCard label="Registered assets" value={motors.length} note="Across plant locations" icon={<Cpu size={18}/>} tone="blue"/><MetricCard label="Healthy" value={healthy} note="Within configured limits" icon={<ShieldCheck size={18}/>} tone="green"/><MetricCard label="At risk" value={warnings + critical} note="Warning or critical" icon={<AlertTriangle size={18}/>} tone="amber"/></div><Panel title="Motor inventory" subtitle="Search, filter, inspect and manage equipment" action={<button className="btn-primary" onClick={() => { setEditingMotorId(null); setTempInput({ name: '', location: '', model: '' }); setShowAddMotor(true) }}><Plus size={14}/>Add motor</button>}><div className="mb-4 flex flex-wrap gap-2"><div className="search-control"><Search size={15}/><input placeholder="Search motor, ID, location..." value={query} onChange={e => setQuery(e.target.value)}/></div><select className="select-control" value={statusFilter} onChange={e => setStatusFilter(e.target.value)}><option>All statuses</option><option>Healthy</option><option>Warning</option><option>Critical</option></select><select className="select-control" value={sortBy} onChange={e => setSortBy(e.target.value as typeof sortBy)} aria-label="Sort motors"><option value="name">Sort: name</option><option value="health">Sort: lowest health</option><option value="vibration">Sort: highest vibration</option><option value="temperature">Sort: highest temperature</option></select><button className="btn-secondary" onClick={() => { setQuery(''); setStatusFilter('All statuses'); setSortBy('name') }}><Filter size={14}/>Reset filters</button><button className="btn-secondary" onClick={exportMotors}><ArrowDownToLine size={14}/>Export CSV</button></div><div className="table-wrap"><table><thead><tr><th>Asset</th><th>Model / location</th><th>Vibration</th><th>Temperature</th><th>RPM</th><th>Health</th><th>Status</th><th>Actions</th></tr></thead><tbody>{filteredMotors.map(m => <tr key={m.id}><td><div className="flex items-center gap-3"><div className="table-motor-icon"><Cpu size={15}/></div><div><p className="font-semibold text-slate-200">{m.name}</p><p className="mt-1 text-[10px] text-slate-500">{m.id}</p></div></div></td><td><p className="text-xs text-slate-300">{m.model}</p><p className="mt-1 text-[10px] text-slate-500">{m.location}</p></td><td>{m.vibration.toFixed(1)} <small className="text-slate-500">mm/s</small></td><td>{unit === 'C' ? `${m.temperature}°C` : `${(m.temperature * 1.8 + 32).toFixed(1)}°F`}</td><td>{m.rpm.toLocaleString()}</td><td><div className="flex items-center gap-2"><div className="health-bar"><i style={{ width: `${m.health}%` }}/></div><span className="text-xs">{m.health}%</span></div></td><td><StatusPill status={m.status}/></td><td><button className="table-action" title="Edit motor" onClick={() => { setEditingMotorId(m.id); setTempInput({ name: m.name, location: m.location, model: m.model }); setShowAddMotor(true) }}><Settings2 size={14}/></button><button className="table-action ml-1" title="Generate reading" onClick={() => { const r = makeReading(m); setHistory(p => [...p,r].slice(-60)); toastMsg(`Reading generated for ${m.name}`) }}><RefreshCw size={14}/></button><button className="table-action ml-1 text-rose-300" title="Delete motor" onClick={() => deleteMotor(m)}><X size={14}/></button></td></tr>)}</tbody></table>{filteredMotors.length === 0 && <EmptyState title="No matching motors" text="Try another search term or reset the filters." />}</div></Panel></>}

        {page === 'Analytics' && <><section className="mb-5 grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Samples in window" value={mergedHistory.length} note="Rolling window capped at 60" icon={<Waves size={18}/>} tone="blue"/><MetricCard label="Avg. vibration" value={(mergedHistory.reduce((s,r) => s+r.vibration,0)/Math.max(1,mergedHistory.length)).toFixed(2)} unit="mm/s" note="Mean of displayed samples" icon={<Activity size={18}/>} tone="green"/><MetricCard label="Avg. temperature" value={(mergedHistory.reduce((s,r) => s+r.temperature,0)/Math.max(1,mergedHistory.length)).toFixed(1)} unit="°C" note="Raw Celsius baseline" icon={<Thermometer size={18}/>} tone="amber"/><MetricCard label="Abnormal samples" value={mergedHistory.filter(r => r.status !== 'Healthy').length} note="Warning or critical readings" icon={<AlertTriangle size={18}/>} tone="red"/></section><div className="grid grid-cols-1 gap-5 xl:grid-cols-2"><Panel title="Vibration trend" subtitle="Time-series · millimetres per second"><div className="h-[300px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={trendData}><CartesianGrid stroke="rgba(148,163,184,.1)" vertical={false}/><XAxis dataKey="time" tick={{ fill: '#64748b', fontSize: 10 }} tickLine={false} axisLine={false}/><YAxis tick={{ fill: '#64748b', fontSize: 10 }} tickLine={false} axisLine={false}/><Tooltip contentStyle={{ background: '#0d202b', border: '1px solid #243945', borderRadius: 10 }}/><Line dataKey="vibration" type="monotone" stroke="#35d6a1" strokeWidth={2} dot={false} activeDot={{ r: 4 }}/></LineChart></ResponsiveContainer></div></Panel><Panel title="Temperature trend" subtitle="Time-series · degrees Celsius"><div className="h-[300px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trendData}><CartesianGrid stroke="rgba(148,163,184,.1)" vertical={false}/><XAxis dataKey="time" tick={{ fill: '#64748b', fontSize: 10 }} tickLine={false} axisLine={false}/><YAxis tick={{ fill: '#64748b', fontSize: 10 }} tickLine={false} axisLine={false}/><Tooltip contentStyle={{ background: '#0d202b', border: '1px solid #243945', borderRadius: 10 }}/><Area dataKey="temperature" type="monotone" stroke="#f6b75d" fill="#f6b75d" fillOpacity={.1} strokeWidth={2}/></AreaChart></ResponsiveContainer></div></Panel></div><Panel title="Raw telemetry log" subtitle="Latest samples · export available" action={<button className="btn-secondary" onClick={exportReadings}><ArrowDownToLine size={14}/>Export CSV</button>}><div className="table-wrap"><table><thead><tr><th>Timestamp</th><th>Motor</th><th>Vibration</th><th>Temp.</th><th>RPM</th><th>Current</th><th>Source</th></tr></thead><tbody>{mergedHistory.slice(-15).reverse().map(r => <tr key={r.id}><td>{fmtDate(r.timestamp)}</td><td>{r.motorName}</td><td>{r.vibration.toFixed(2)} mm/s</td><td>{r.temperature.toFixed(1)}°C</td><td>{r.rpm}</td><td>{r.current.toFixed(1)} A</td><td><span className="source-tag">{r.simulated ? 'SIMULATED' : 'API'}</span></td></tr>)}</tbody></table></div></Panel></>}

        {page === 'Alerts' && <><div className="mb-5 grid grid-cols-1 gap-3 sm:grid-cols-3"><MetricCard label="Open alerts" value={unacknowledged} note="Need operator review" icon={<Bell size={18}/>} tone="amber"/><MetricCard label="Critical events" value={alerts.filter(a => a.severity === 'Critical' && !a.acknowledged).length} note="Immediate attention" icon={<AlertCircle size={18}/>} tone="red"/><MetricCard label="Acknowledged" value={alerts.filter(a => a.acknowledged).length} note="Reviewed by operator" icon={<Check size={18}/>} tone="green"/></div><Panel title="Alert center" subtitle="Vibration and temperature threshold events" action={<button className="btn-secondary" onClick={() => setAlerts(prev => prev.map(a => ({ ...a, acknowledged: true })))}><Check size={14}/>Acknowledge all</button>}>{alerts.map(a => <div key={a.id} className={`alert-card ${a.severity === 'Critical' ? 'alert-card-critical' : ''}`}><div className={`alert-symbol ${a.severity === 'Critical' ? 'alert-symbol-red' : 'alert-symbol-amber'}`}><AlertTriangle size={17}/></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="text-sm font-semibold text-slate-100">{a.motorName}</h3><StatusPill status={a.severity}/>{a.acknowledged && <span className="source-tag">ACKNOWLEDGED</span>}</div><p className="mt-2 text-sm text-slate-400">{a.message}</p><p className="mt-2 text-[11px] text-slate-600">{a.id} · {fmtDate(a.timestamp)}</p></div>{!a.acknowledged && <button className="btn-secondary shrink-0" onClick={() => acknowledge(a.id)}><Check size={14}/>Acknowledge</button>}</div>)}{alerts.length === 0 && <EmptyState title="No alerts" text="New abnormal sensor readings will appear here."/>}</Panel></>}

        {page === 'Maintenance' && <><div className="mb-5 grid grid-cols-1 gap-3 sm:grid-cols-3"><MetricCard label="Open work orders" value={maintenance.filter(w => w.status !== 'Completed').length} note="Scheduled or in progress" icon={<Wrench size={18}/>} tone="blue"/><MetricCard label="High priority" value={maintenance.filter(w => w.priority === 'High' && w.status !== 'Completed').length} note="Prioritize these tasks" icon={<AlertTriangle size={18}/>} tone="red"/><MetricCard label="Completed" value={maintenance.filter(w => w.status === 'Completed').length} note="Work orders closed" icon={<Check size={18}/>} tone="green"/></div><Panel title="Preventive maintenance" subtitle="Plan service activity and track completion" action={<button className="btn-primary" onClick={() => setShowAddWork(true)}><Plus size={14}/>New work order</button>}><div className="table-wrap"><table><thead><tr><th>Work order</th><th>Motor</th><th>Task</th><th>Due date</th><th>Priority</th><th>Status</th><th>Update</th></tr></thead><tbody>{maintenance.map(w => <tr key={w.id}><td className="font-semibold text-slate-300">{w.id}</td><td>{w.motorName}</td><td>{w.task}</td><td>{new Date(`${w.dueDate}T12:00:00`).toLocaleDateString()}</td><td><span className={`priority-label priority-${w.priority.toLowerCase()}`}>{w.priority}</span></td><td><span className={`work-status work-${w.status.toLowerCase().replace(' ','-')}`}>{w.status}</span></td><td><button className="btn-secondary compact" onClick={() => updateWorkStatus(w)}>{w.status === 'Completed' ? 'Reopen' : 'Advance status'}</button></td></tr>)}</tbody></table></div></Panel><Panel title="Maintenance strategy" subtitle="Recommended next actions"><div className="grid grid-cols-1 gap-3 md:grid-cols-3"><div className="strategy-card"><div className="metric-icon icon-red"><AlertTriangle size={18}/></div><h3>Critical condition</h3><p>Inspect the cooling pump bearings and alignment first; its current vibration is above the configured threshold.</p></div><div className="strategy-card"><div className="metric-icon icon-amber"><Thermometer size={18}/></div><h3>Thermal review</h3><p>Verify ventilation and bearing lubrication on motors with elevated casing temperatures.</p></div><div className="strategy-card"><div className="metric-icon icon-green"><Clock3 size={18}/></div><h3>Routine servicing</h3><p>Record service date, work performed and technician notes to build a maintenance history.</p></div></div></Panel></>}

        {page === 'Reports' && <><section className="mb-5 grid grid-cols-1 gap-3 sm:grid-cols-3"><MetricCard label="Telemetry samples" value={mergedHistory.length} note="Current rolling window" icon={<Activity size={18}/>} tone="blue"/><MetricCard label="Assets tracked" value={motors.length} note="Registered motor inventory" icon={<Cpu size={18}/>} tone="green"/><MetricCard label="Open work orders" value={maintenance.filter(w => w.status !== 'Completed').length} note="Maintenance queue" icon={<Wrench size={18}/>} tone="amber"/></section><Panel title="Export center" subtitle="Download operational records as CSV files"><div className="grid grid-cols-1 gap-4 md:grid-cols-2"><div className="export-card"><div className="export-icon"><Activity size={20}/></div><div className="flex-1"><h3>Telemetry readings</h3><p>Timestamped vibration, temperature, RPM, current and health readings from the last 60 samples.</p><span className="source-tag">CSV · {mergedHistory.length} rows</span></div><button className="btn-primary" onClick={exportReadings}><ArrowDownToLine size={14}/>Export</button></div><div className="export-card"><div className="export-icon"><Cpu size={20}/></div><div className="flex-1"><h3>Motor inventory</h3><p>Asset IDs, locations, motor models, latest condition and last service date.</p><span className="source-tag">CSV · {motors.length} assets</span></div><button className="btn-primary" onClick={exportMotors}><ArrowDownToLine size={14}/>Export</button></div><div className="export-card"><div className="export-icon"><Bell size={20}/></div><div className="flex-1"><h3>Alert log</h3><p>Severity, event message, timestamps and acknowledgement state.</p><span className="source-tag">CSV · {alerts.length} events</span></div><button className="btn-secondary" onClick={() => { downloadCsv(alerts as unknown as Record<string, unknown>[], 'motorvibe-alerts.csv'); toastMsg('Alert log exported') }}><ArrowDownToLine size={14}/>Export</button></div><div className="export-card"><div className="export-icon"><Wrench size={20}/></div><div className="flex-1"><h3>Maintenance plan</h3><p>Scheduled maintenance, priorities, due dates and work order status.</p><span className="source-tag">CSV · {maintenance.length} work orders</span></div><button className="btn-secondary" onClick={() => { downloadCsv(maintenance as unknown as Record<string, unknown>[], 'motorvibe-maintenance.csv'); toastMsg('Maintenance plan exported') }}><ArrowDownToLine size={14}/>Export</button></div></div></Panel><Panel title="Report integrity" subtitle="Read this before presenting results"><div className="notice-box"><AlertCircle size={18}/><div><p className="font-semibold text-slate-200">Demo telemetry is simulated</p><p className="mt-1 text-sm leading-6 text-slate-400">These files are generated from the dashboard's current state. They are useful for UI demonstration and lab evaluation; they are not measurements from a physical motor unless a real telemetry source is connected.</p></div></div></Panel></>}

        {page === 'Engineering labs' && <><section className="mb-5"><div className="mb-3 flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-semibold text-white">CO2–CO4 interactive lab suite</h2><p className="mt-1 text-xs text-slate-500">The syllabus sensor exercises implemented in one dashboard.</p></div><span className="source-tag">REACT · TYPESCRIPT · TAILWIND</span></div><div className="flex flex-wrap gap-2">{(['TempDash','PressureDash','VoltDash','PowerDash','HumidDash','SpeedDash','PulseDash'] as const).map(t => <button key={t} className={`lab-tab ${labTab === t ? 'lab-tab-active' : ''}`} onClick={() => { setLabTab(t); setLabHistory([]); setLabRunning(false); setLabUnit('primary'); setLabValue(t === 'TempDash' ? 25 : t === 'PressureDash' ? 101325 : t === 'VoltDash' ? 5 : t === 'PowerDash' ? 4 : t === 'HumidDash' ? 50 : t === 'SpeedDash' ? 65 : 75) }}>{t}</button>)}</div></section><div className="grid grid-cols-1 gap-5 xl:grid-cols-[minmax(0,1.4fr)_minmax(280px,.8fr)]"><Panel title={`${labTab} live simulator`} subtitle="React state + props + conditional rendering + typed readings" action={<span className="source-tag">DEMO SENSOR</span>}><div className="lab-value-card"><div className="flex items-center gap-2 text-xs text-slate-400"><Radio size={14} className="text-emerald-300"/>Latest reading</div><div className={`mt-3 text-5xl font-semibold tracking-tight ${isLabAbnormal(labTab, labValue) ? 'text-rose-300' : 'text-white'}`}>{labTab === 'TempDash' && labUnit === 'alternate' ? (labValue * 1.8 + 32).toFixed(1) : labTab === 'PressureDash' && labUnit === 'alternate' ? (labValue / 100000).toFixed(2) : labTab === 'VoltDash' && labUnit === 'alternate' ? (labValue / 2).toFixed(2) : labValue}<span className="ml-2 text-base text-slate-500">{labTab === 'TempDash' ? (labUnit === 'primary' ? '°C' : '°F') : labTab === 'PressureDash' ? (labUnit === 'primary' ? 'Pa' : 'bar') : labTab === 'VoltDash' ? (labUnit === 'primary' ? 'V' : 'A') : labTab === 'PowerDash' ? 'W' : labTab === 'HumidDash' ? '%' : labTab === 'SpeedDash' ? 'km/h' : 'bpm'}</span></div><div className="mt-4">{isLabAbnormal(labTab, labValue) ? <StatusPill status="Critical"/> : <StatusPill status="Healthy"/>}<p className="mt-3 text-xs text-slate-500">{labTab === 'TempDash' ? 'Abnormal when > 40°C' : labTab === 'PressureDash' ? 'Switch Pa / bar · abnormal when > 2 bar' : labTab === 'VoltDash' ? 'Switch voltage / current · I = V / 2Ω · abnormal current > 2 A' : labTab === 'PowerDash' ? 'Power computed as P = V × I · abnormal > 6 W' : labTab === 'HumidDash' ? 'Comfortable 40–60% · High > 60% · Low < 40%' : labTab === 'SpeedDash' ? 'Abnormal when > 120 km/h' : 'Abnormal when < 60 or > 100 bpm'}</p></div>{labTab === 'PowerDash' && <p className="mt-3 text-xs text-slate-400">Voltage: <strong className="text-slate-200">{labVoltage} V</strong> · Current: <strong className="text-slate-200">{labCurrent} A</strong> · P = V × I</p>}</div><div className="mt-4 flex flex-wrap gap-2"><button className="btn-primary" onClick={generateLabReading}><Zap size={14}/>Generate reading</button><button className="btn-secondary" onClick={() => setLabUnit(v => v === 'primary' ? 'alternate' : 'primary')}>{labTab === 'TempDash' ? '°C / °F' : labTab === 'PressureDash' ? 'Pa / bar' : labTab === 'VoltDash' ? 'V / A' : 'Toggle view'}</button><button className="btn-secondary" onClick={() => setLabRunning(v => !v)}>{labRunning ? <><Power size={14}/>Stop auto</> : <><Radio size={14}/>Start auto (2s)</>}</button><button className="btn-secondary" onClick={() => { setLabHistory([]); setLabRunning(false) }}><RefreshCw size={14}/>Reset</button></div><div className="mt-6 h-[220px]"><ResponsiveContainer width="100%" height="100%"><LineChart data={labHistory}><CartesianGrid stroke="rgba(148,163,184,.1)" vertical={false}/><XAxis dataKey="time" tick={{ fill: '#64748b', fontSize: 10 }} tickLine={false} axisLine={false}/><YAxis tick={{ fill: '#64748b', fontSize: 10 }} tickLine={false} axisLine={false}/><Tooltip contentStyle={{ background: '#0d202b', border: '1px solid #243945', borderRadius: 10 }}/><Line dataKey="value" type="monotone" stroke="#35d6a1" strokeWidth={2} dot={false}/></LineChart></ResponsiveContainer></div></Panel><div className="space-y-5"><Panel title="Lab calculations" subtitle="Array-method summaries"><div className="grid grid-cols-2 gap-3"><div className="summary-tile"><span>Samples</span><strong>{labHistory.length}</strong></div><div className="summary-tile"><span>Average</span><strong>{labHistory.length ? (labHistory.reduce((s,r) => s+r.value,0)/labHistory.length/(labTab === 'PressureDash' ? 100000 : 1)).toFixed(1) : '—'}</strong></div><div className="summary-tile"><span>Abnormal</span><strong className="text-rose-300">{labHistory.filter(r => isLabAbnormal(labTab,r.value)).length}</strong></div><div className="summary-tile"><span>Update count (ref)</span><strong>{labCount.current}</strong></div></div><p className="mt-4 text-xs leading-5 text-slate-500">The lab stores mutable readings in React state, renders the list with map(), filters abnormal values, calculates average with reduce(), and caps the rolling history to 60 points.</p></Panel><Panel title="SignalDash architecture" subtitle="CO1 · end-to-end data journey"><div className="space-y-2">{[{n:'01',t:'Physical sensor',d:'Measures vibration, temperature, pressure or voltage.'},{n:'02',t:'MQTT broker',d:'Publishes telemetry to interested subscribers.'},{n:'03',t:'Node.js + Express',d:'Validates, timestamps, stores and routes readings.'},{n:'04',t:'Socket.IO / WebSocket or SSE',d:'Pushes updates without constant page refresh.'},{n:'05',t:'React + Recharts',d:'Renders typed state into live cards and time-series charts.'}].map(step => <div key={step.n} className="flex gap-3 rounded-lg border border-white/[.06] bg-[#0a1a24] p-3"><span className="grid h-7 w-7 flex-none place-items-center rounded-lg bg-emerald-400/[.08] text-[10px] font-bold text-emerald-300">{step.n}</span><div><p className="text-xs font-semibold text-slate-200">{step.t}</p><p className="mt-1 text-[10px] leading-5 text-slate-500">{step.d}</p></div></div>)}</div><p className="mt-3 text-[10px] leading-5 text-slate-600">MQTT hardware ingestion is shown as the target architecture; this starter currently simulates sensor values and provides API / real-time transport demonstrations.</p></Panel><Panel title="Course concepts in this view" subtitle="Mapped to the supplied course handouts"><ul className="concept-list"><li><Check size={14}/>React components, props and state</li><li><Check size={14}/>useEffect timer lifecycle + cleanup</li><li><Check size={14}/>useRef update counter</li><li><Check size={14}/>TypeScript interfaces + unit conversion</li><li><Check size={14}/>Semantic HTML5 + Tailwind utility styling</li><li><Check size={14}/>Recharts time-series visualization</li><li><Check size={14}/>Emergency stop / restart controls</li></ul></Panel></div></div><Panel title="Async / await + Fetch API lab" subtitle="CO2 · JSON telemetry, loading state and network/API-key error handling"><div className="flex flex-wrap items-center justify-between gap-3"><div className="max-w-2xl"><p className="text-sm font-semibold text-slate-200">Campus weather telemetry · Hyderabad</p><p className="mt-1 text-xs leading-5 text-slate-500">Fetches temperature, humidity and pressure as JSON while keeping the interface responsive. If the network is unavailable, a clear error is shown.</p></div><button className="btn-primary" onClick={fetchWeatherLab} disabled={apiLabLoading}>{apiLabLoading ? <RefreshCw size={14} className="animate-spin"/> : <Radio size={14}/>} {apiLabLoading ? 'Fetching…' : 'Fetch live weather'}</button></div>{apiLabResult && <div className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-3"><div className="summary-tile"><span>Temperature</span><strong>{apiLabResult.temperature}°C</strong></div><div className="summary-tile"><span>Humidity</span><strong>{apiLabResult.humidity}%</strong></div><div className="summary-tile"><span>Pressure</span><strong>{apiLabResult.pressure} hPa</strong></div></div>}<div className="mt-4 border-t border-white/[.06] pt-4"><label className="field-label">API key error-handling exercise<input className="field-input max-w-md" value={apiKeyInput} onChange={e => setApiKeyInput(e.target.value)} placeholder="Leave empty to test missing-key validation"/></label><button className="btn-secondary mt-3" onClick={validateApiKeyDemo}>Validate key input</button></div>{apiLabError && <div className="auth-error mt-4"><AlertCircle size={15}/><span>{apiLabError}</span></div>}</Panel></>}
        <footer className="app-footer"><span>© 2026 MotorVibe Intelligence</span><span className="flex items-center gap-2"><span className="live-dot"/>{apiStatus.mode === 'connected' ? 'API connected' : 'SIMULATED DATA'} <span className="text-slate-700">·</span> CO-aligned capstone prototype</span></footer>
      </div>
    </main>
    {showAddMotor && <Modal title={editingMotorId ? 'Edit motor' : 'Register motor'} onClose={() => { setShowAddMotor(false); setEditingMotorId(null) }}><form onSubmit={addMotor} className="space-y-4"><Field label="Motor name" value={tempInput.name} onChange={v => setTempInput(p => ({...p,name:v}))} placeholder="e.g. Compressor Motor 06" required/><Field label="Location" value={tempInput.location} onChange={v => setTempInput(p => ({...p,location:v}))} placeholder="e.g. Utilities · Zone 2" required/><Field label="Motor model" value={tempInput.model} onChange={v => setTempInput(p => ({...p,model:v}))} placeholder="e.g. Siemens 1LE1"/><div className="flex justify-end gap-2 pt-2"><button type="button" className="btn-secondary" onClick={() => setShowAddMotor(false)}>Cancel</button><button className="btn-primary" type="submit"><Plus size={14}/>{editingMotorId ? 'Save changes' : 'Add motor'}</button></div></form></Modal>}
    {showAddWork && <Modal title="Create maintenance work order" onClose={() => setShowAddWork(false)}><form onSubmit={addWork} className="space-y-4"><label className="field-label">Motor<select className="field-input" value={workInput.motorId} onChange={e => setWorkInput(p => ({...p,motorId:e.target.value}))}>{motors.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}</select></label><Field label="Maintenance task" value={workInput.task} onChange={v => setWorkInput(p => ({...p,task:v}))} placeholder="e.g. Inspect bearings" required/><label className="field-label">Due date<input type="date" className="field-input" value={workInput.dueDate} onChange={e => setWorkInput(p => ({...p,dueDate:e.target.value}))} required/></label><label className="field-label">Priority<select className="field-input" value={workInput.priority} onChange={e => setWorkInput(p => ({...p,priority:e.target.value as MaintenanceItem['priority']}))}><option>Low</option><option>Medium</option><option>High</option></select></label><div className="flex justify-end gap-2 pt-2"><button type="button" className="btn-secondary" onClick={() => setShowAddWork(false)}>Cancel</button><button className="btn-primary" type="submit"><Plus size={14}/>Create work order</button></div></form></Modal>}
    {toast && <div className="toast"><Check size={16}/>{toast}</div>}
  </div>
}
function AuthScreen({ mode, setMode, name, setName, email, setEmail, password, setPassword, error, loading, onSubmit, onDemo }: {
  mode: 'login'|'register'; setMode: (mode: 'login'|'register') => void; name: string; setName: (v: string) => void;
  email: string; setEmail: (v: string) => void; password: string; setPassword: (v: string) => void;
  error: string; loading: boolean; onSubmit: (e: FormEvent) => void; onDemo: () => void;
}) {
  return <main className="auth-shell"><section className="auth-story"><Brand/><div className="auth-story-copy"><span className="hero-tag"><Activity size={12}/> MOTOR INTELLIGENCE PLATFORM</span><h1>Make every<br/>motor <span>measurably</span><br/>more reliable.</h1><p>Monitor asset health, spot abnormal vibration and temperature, and plan maintenance before downtime becomes expensive.</p><div className="auth-feature"><span><ShieldCheck size={17}/></span><div><strong>Condition-first monitoring</strong><small>One workspace for health, alerts and maintenance.</small></div></div><div className="auth-feature"><span><Waves size={17}/></span><div><strong>Real-time telemetry concepts</strong><small>REST, WebSocket / Socket.IO, SSE and live charts.</small></div></div><div className="auth-feature"><span><Database size={17}/></span><div><strong>Full-stack course coverage</strong><small>React, TypeScript, Tailwind, Express and PostgreSQL.</small></div></div></div><div className="auth-story-foot">MOTORVIBE INTELLIGENCE · COURSE CAPSTONE PROTOTYPE</div></section><section className="auth-form-wrap"><div className="auth-form-card"><div className="mb-7"><p className="text-[10px] font-bold tracking-[.18em] text-emerald-300">{mode === 'login' ? 'WELCOME BACK' : 'CREATE YOUR ACCOUNT'}</p><h2 className="mt-2 text-2xl font-semibold tracking-tight text-white">{mode === 'login' ? 'Sign in to MotorVibe' : 'Join MotorVibe'}</h2><p className="mt-2 text-xs leading-5 text-slate-500">{mode === 'login' ? 'Access your motor fleet and operational insights.' : 'Create an account to access the monitoring workspace.'}</p></div><form onSubmit={onSubmit} className="space-y-4">{mode === 'register' && <label className="field-label">Full name<input className="field-input" value={name} onChange={e => setName(e.target.value)} placeholder="Your name" required minLength={2}/></label>}<label className="field-label">Email address<input type="email" className="field-input" value={email} onChange={e => setEmail(e.target.value)} placeholder="operator@company.com" required/></label><label className="field-label">Password<input type="password" className="field-input" value={password} onChange={e => setPassword(e.target.value)} placeholder={mode === 'register' ? 'At least 10 characters' : 'Enter your password'} minLength={mode === 'register' ? 10 : 1} required/></label>{error && <div className="auth-error"><AlertCircle size={15}/><span>{error}</span></div>}<button type="submit" disabled={loading} className="btn-primary w-full !py-3">{loading ? 'Connecting…' : mode === 'login' ? 'Sign in' : 'Create account'}<ChevronDown size={14} className="-rotate-90"/></button></form><div className="auth-switch"><span>{mode === 'login' ? "Don't have an account?" : 'Already registered?'}</span><button onClick={() => { setMode(mode === 'login' ? 'register' : 'login') }} type="button">{mode === 'login' ? 'Create account' : 'Sign in'}</button></div><div className="auth-divider"><span>OR</span></div><button className="btn-secondary w-full !py-3" onClick={onDemo} type="button"><Activity size={15}/>Continue in demo mode</button><p className="mt-4 text-center text-[10px] leading-5 text-slate-600">Demo mode uses clearly labelled simulated readings. Backend account creation requires PostgreSQL to be configured.</p></div><div className="mt-5 text-center text-[10px] text-slate-700">© 2026 MotorVibe · Secure engineering telemetry</div></section></main>
}
function isLabAbnormal(tab: 'TempDash'|'PressureDash'|'VoltDash'|'PowerDash'|'HumidDash'|'SpeedDash'|'PulseDash', value: number) {
  if (tab === 'TempDash') return value > 40
  if (tab === 'PressureDash') return value > 200000
  if (tab === 'VoltDash') return (value / 2) > 2
  if (tab === 'PowerDash') return value > 6
  if (tab === 'HumidDash') return value < 40 || value > 60
  if (tab === 'SpeedDash') return value > 120
  return value < 60 || value > 100
}
function Modal({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  return <div className="modal-backdrop" role="presentation" onMouseDown={e => { if (e.target === e.currentTarget) onClose() }}><section className="modal" role="dialog" aria-modal="true" aria-label={title}><div className="mb-5 flex items-center justify-between"><h2 className="text-lg font-semibold text-white">{title}</h2><button className="icon-button" onClick={onClose} aria-label="Close modal"><X size={16}/></button></div>{children}</section></div>
}
function Field({ label, value, onChange, placeholder, required = false }: { label: string; value: string; onChange: (value: string) => void; placeholder: string; required?: boolean }) {
  return <label className="field-label">{label}<input className="field-input" value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} required={required}/></label>
}
export default App
